def test_pdb_teardown_skipped_class(pytester: Pytester) -> None:
    """Check that with --pdb, tearDown is not run for skipped unittest classes.

    With --pdb, ``tearDown`` is postponed so the pdb prompt can inspect the
    test instance. Skipped test cases must not be postponed (nor run at all),
    otherwise ``tearDown`` would still be executed for them.
    """
    pytester.makepyfile(
        """
        import unittest

        @unittest.skip("hello")
        class MyTestCase(unittest.TestCase):
            def setUp(self):
                raise Exception("setUp called")
            def test_one(self):
                pass
            def tearDown(self):
                raise Exception("tearDown called")
    """
    )
    result = pytester.runpytest("--pdb")
    # 1 skipped and no failure (otherwise --pdb would have been entered).
    result.assert_outcomes(skipped=1)
    assert result.ret == 0


