@pytest.mark.sphinx('html', testroot='ext-autodoc')
def test_autodoc_public_and_private_meta_for_attributes(app):
    options = {"members": None}
    actual = do_autodoc(app, 'module', 'target.public_private_attr', options)
    # ``#: :meta public:`` makes a private-looking attribute shown
    assert '.. py:data:: _public_attr' in actual
    # while a plain private attribute stays hidden
    assert not any('.. py:data:: _private' in line for line in actual)
    # normal public attributes are still shown
    assert any('py:data:: public' in line for line in actual)


@pytest.mark.sphinx('html', testroot='ext-autodoc')
def test_autodoc_public_and_private_meta_for_class_attributes(app):
    options = {"members": None}
    actual = do_autodoc(app, 'module', 'target.public_private_attr', options)
    # class attributes with ``:meta public:`` / ``:meta private:`` are honored too
    assert '.. py:attribute:: Foo.public_attr' in actual
    assert '.. py:attribute:: Foo._private_attr' not in actual
    assert '.. py:attribute:: Foo._public_attr' in actual

