def _set_xy(self, xy):
    # Make an independent copy of array-like *xy* so that mutating the
    # passed-in array does not alter the annotation (GH #17202).  Other
    # types (e.g. (datetime, float) tuples) are kept as-is so that unit
    # conversion still works.
    if isinstance(xy, np.ndarray):
        self._xy = tuple(np.array(xy, copy=True).ravel().tolist())
    else:
        self._xy = xy
